//! 🔗️ A native reference restriction reads original pages and individual source keys before admitting removal.
use super::*;
use semio_framework_value_persistent::list::persistent::{PersistentList,PersistentListRead,PersistentListReadStep};
/// 🧭️ Each authored relation names its actual referencing collection and original scalar or vector key source.
pub trait RowReferenceSource:Send+Sync+'static{type Row:RetireOwned+Send+Sync;fn rows(original:RetainedCloneRef<'_,EnergyModelSnapshot>)->RetainedCloneRef<'_,PersistentList<Self::Row>>;fn len(row:&Self::Row)->usize;fn key(row:&Self::Row,index:usize)->Result<u32,ValueError>;}
/// 🧳️ The scan retains the current original row while a wide reference vector is inspected one key per turn.
pub struct ReferenceRowGuard<S:RowReferenceSource>{original:Option<RetainedCloneBinding>,deleted:Option<RetainedCloneBinding>,reader:PersistentListRead<S::Row>,row:Option<RetainedOwnedProjection<S::Row>>,index:usize,allowed:Option<bool>,phase:u8,closing:bool}
impl<S:RowReferenceSource,R:EntityRow> RowDeletionGuard<R> for ReferenceRowGuard<S>{
 fn new()->Self{Self{original:None,deleted:None,reader:PersistentListRead::new(),row:None,index:0,allowed:None,phase:0,closing:false}}
 fn demand(&self,row:RetainedCloneRef<'_,R>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase==99{return Err(invalid());}row.check_binding(&self.deleted)?;original.check_binding(&self.original)?;match self.phase{0=>nested(scalar(row.binding_copy_bytes()),1),1=>nested(scalar(original.binding_copy_bytes()),1),2=>nested(self.reader.demand(S::rows(original))?,2*size_of::<Option<RetainedOwnedProjection<S::Row>>>()+2*size_of::<usize>()+1),3=>Ok(scalar(size_of::<u32>()*2+4*size_of::<usize>()+2*size_of::<Option<bool>>()+1)),4=>{let row=self.row.as_ref().ok_or_else(invalid)?;if row.terminal_is_empty(){Ok(scalar(2*size_of::<Option<RetainedOwnedProjection<S::Row>>>()+1))}else{row.close_demand(body)}},_=>Err(invalid())}}
 fn advance(&mut self,deleted:RetainedCloneRef<'_,R>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=<Self as RowDeletionGuard<R>>::demand(self,deleted,original,body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let mut p=receipt(d);match self.phase{0=>{p=add(deleted.bind(&mut self.deleted,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=1;},1=>{p=add(original.bind(&mut self.original,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=2;},2=>{let extra=2*size_of::<Option<RetainedOwnedProjection<S::Row>>>()+2*size_of::<usize>()+1;let step=self.reader.advance(S::rows(original),child(g,extra)).map_err(|e|tag(e,extra))?;p=add(step.progress(),extra)?;match step{PersistentListReadStep::Row(_,_,row)=>{let(row,progress)=row.retain_owned(child(g,extra)).map_err(|e|tag(e,extra))?;if progress.retained_capacity_bytes!=0||progress.released_bytes!=0{return Err(invalid().with_retained_progress(p));}self.row=Some(row);self.index=0;self.phase=3;},PersistentListReadStep::Complete(_)=>{self.allowed=Some(true);self.phase=99;},_=>{}}},3=>{let row=self.row.as_ref().ok_or_else(invalid)?.borrow()?;if self.index>=S::len(row.get()){self.phase=4;}else{let found=S::key(row.get(),self.index)?==deleted.get().entity_id();self.index+=1;if found{self.allowed=Some(false);self.phase=4;}}},4=>{let row=self.row.as_mut().ok_or_else(invalid)?;if row.terminal_is_empty(){drop(self.row.take());self.phase=if self.allowed==Some(false){99}else{2};}else{p=row.close_step(g)?.progress();}},_=>return Err(invalid())}semio_framework_value::retained_clone::admit_retained_clone_progress(g,p,"original Energy reference restriction")?;Ok(if self.phase==99{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 fn result(&self)->Option<bool>{if !self.closing&&self.phase==99{self.allowed}else{None}}
 fn begin_close(&mut self){self.closing=true;self.reader.begin_close();}
}
impl<S:RowReferenceSource> CursorClose for ReferenceRowGuard<S>{
 fn close_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}if let Some(row)=self.row.as_ref(){return if row.terminal_is_empty(){Ok(scalar(2*size_of::<Option<RetainedOwnedProjection<S::Row>>>()))}else{row.close_demand(b)};}if !self.reader.terminal_is_empty(){return self.reader.close_demand(b);}RetainedCloneBinding::close_demand(if self.deleted.is_some(){&self.deleted}else{&self.original},b)}
 fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}if let Some(row)=self.row.as_mut(){if row.terminal_is_empty(){drop(self.row.take());return Ok(RetainedCloneStep::Progress(receipt(d)));}return row.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()));}if !self.reader.terminal_is_empty(){return self.reader.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()));}let s=RetainedCloneBinding::close_one(if self.deleted.is_some(){&mut self.deleted}else{&mut self.original},g)?;Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(s.progress())}else{RetainedCloneStep::Progress(s.progress())})}
 fn terminal_is_empty(&self)->bool{self.closing&&self.row.is_none()&&self.reader.terminal_is_empty()&&self.deleted.is_none()&&self.original.is_none()}
}
impl<S:RowReferenceSource> Drop for ReferenceRowGuard<S>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original reference restriction retains source page custody");}}
